insert into public.people (slug, name, "group", role_en, role_id, bio_en, bio_id, photo, social_url, sort, published) values
  ('ir-dzikri-firmansyah-hakam-st-pgdip-msc-phd-cfpr', 'Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., CFP®', 'leadership', 'Executive Director, IEEF', 'Direktur Eksekutif, IEEF', 'Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., CFP® is the Executive Director of the Institute for Energy, Economics and Finance (IEEF) and an academic at the School of Business and Management, Institut Teknologi Bandung (SBM ITB). He is recognized as an expert in energy economics, finance, electricity policy, infrastructure investment, and energy transition. Through IEEF, he leads the development of strategic research and policy studies focusing on strengthening energy governance, sustainable finance, market design, and accelerating an energy transition that delivers meaningful economic impact for Indonesia. He has a strong professional track record in the energy and power sector, with nearly two decades of experience across industry, government, state-owned enterprises, and academia.

As a researcher and academic, he actively produces internationally recognized scholarly publications, including articles in Scopus Q1-indexed journals in the fields of energy, sustainability, economics, and public policy. He also leads various competitive research projects and grants related to electric vehicles, renewable energy, carbon markets, renewable energy certificates, green hydrogen, and energy transition financing.

He has been entrusted with various strategic projects involving national and international institutions. His engagements include investment feasibility studies for electricity interconnection projects, input-output-based economic impact analysis, carbon market and REC assessments, household gas network studies, and executive capacity-building programs in the energy sector. These roles demonstrate his ability to bridge academic analysis, industry needs, and practical policy recommendations.

He earned his Ph.D. in Economics, with a focus on Energy Economics, Law, and Policy, from the University of Dundee, United Kingdom, through the LPDP scholarship. He also obtained an M.Sc. in Management Science from the University of Dundee through the Chevening Scholarship, a Pg.Dip. in Islamic Economics, Finance, and Banking with Distinction, and an academic background in power engineering from Institut Teknologi Bandung. With his combination of professional experience, academic achievements, international publications, and research leadership, he actively contributes to advancing Indonesia’s energy transition in a more measurable, inclusive, and economically impactful manner.', null, 'repo:migrated/people/ir-dzikri-firmansyah-hakam-st-pgdip-msc-phd-cfpr.webp', 'https://www.instagram.com/dzikrihakam/', 1, true),
  ('yudo-anggoro-stmsmphd', 'Yudo Anggoro, S.T.,M.S.M.,Ph.D', 'researcher', 'Director, Center for Policy and Public Management, SBM ITB', 'Direktur, Center for Policy and Public Management, SBM ITB', 'Yudo Anggoro, Ph.D. is the Director of the Center for Policy and Public Management at the School of Business and Management, Institut Teknologi Bandung (SBM ITB), as well as an academic and policy strategist in public policy, energy transition, industrial competitiveness, and sustainable investment. He previously led the MBA Jakarta Campus at SBM ITB and initiated flagship programs such as the Energy Executive MBA (ENEMBA) and the Sustainability Executive MBA (STEMBA).

He has extensive experience in policy research, strategic consulting, and corporate governance. He currently serves as a member of the Risk Management and Business Development Committee at PT Perusahaan Gas Negara Tbk, and previously served as a member of the Audit and GCG Committee at PT Transportasi Jakarta. His engagements cover policy studies, energy transition, carbon markets, green steel decarbonization, electricity export, leadership development, and corporate strategy optimization.

As an academic, he actively produces international publications and policy briefs on corporate foresight, ESG policy, renewable energy, smart cities, public governance, and green transition strategies. He earned his Ph.D. in Public Policy from the University of North Carolina at Charlotte as a Fulbright Scholar, and has an academic background in Management Science and Industrial Engineering from Institut Teknologi Bandung. With his combination of academic experience, institutional leadership, policy research, and strategic advisory work, he actively contributes to strengthening public policy, industrial competitiveness, and sustainable transition in Indonesia.', null, 'repo:migrated/people/yudo-anggoro-stmsmphd.webp', 'https://www.linkedin.com/in/yudoanggoro/', 2, true),
  ('dr-erman-a-sumirat-se-mbuss-csa-crp-cibcwm-ak', 'Dr. Erman A. Sumirat, SE., MBuss., CSA., CRP., CIB., CWM., Ak.', 'researcher', 'Strategic Finance, Investment and Risk Management', 'Keuangan Strategis, Investasi, dan Manajemen Risiko', 'Dr. Erman A. Sumirat, SE., MBuss., CSA., CRP., CIB., CWM., Ak. is an academic, consultant, and senior practitioner in strategic finance, investment, risk management, ESG, and carbon finance. He is active as a lecturer in the MBA program at SBM ITB and Universitas Padjadjaran, and currently serves as a Committee Board Member at Pertamina Hulu Energi, Senior Advisor to the Board of Directors of Telkom Indonesia Group, and Personal Qualification Assessor for SOE executives.

He has more than 25 years of professional experience across various institutions, including Arthur Andersen, Ernst & Young, Accenture, Sindicatum Carbon Capital, Agrinergy, and LAPI ITB. His engagements cover corporate finance advisory, valuation, feasibility studies, ESG financing, carbon credit management, public-private partnership, and executive talent mapping.

He earned his Doctorate in Business Management from Universitas Padjadjaran, Master of Business in Banking and Finance from Monash University, Australia, and Bachelor’s degree in Accounting from Universitas Padjadjaran. With his strong professional experience, certifications, and consulting track record, he actively contributes to strengthening financial governance, risk management, and sustainable financing in Indonesia.', null, 'repo:migrated/people/dr-erman-a-sumirat-se-mbuss-csa-crp-cibcwm-ak.webp', 'https://www.linkedin.com/in/erman-arif-sumirat-eas-32946a65/', 3, true),
  ('atika-irawan-smn-msc-phd-cand', 'Atika Irawan, S.Mn., M.Sc., Ph.D (Cand.)', 'researcher', 'Lecturer, SBM ITB: Finance and Islamic Finance', 'Dosen SBM ITB: Keuangan dan Keuangan Syariah', 'Atika Irawan, S.Mn., M.Sc., Ph.D. (Cand.) is a lecturer at the School of Business and Management, Institut Teknologi Bandung (SBM ITB), and an academic in the fields of finance, Islamic finance, financial literacy, fintech, and business feasibility. She is also a Doctoral Candidate with expertise in the development of financial research and education.

She actively produces publications and research on Islamic banking efficiency, Islamic financing, fintech adoption, corporate social responsibility, financial literacy, and business feasibility studies. One of her notable achievements is being selected as Best Presenter at the Islamic Economic Society United Kingdom 2021 through her research on Islamic banking growth in Indonesia.

She earned her M.Sc. in Islamic Finance and Management from Durham University, United Kingdom, and her Bachelor’s Degree from SBM ITB with a concentration in Finance. She also holds several professional certifications, including Certified Business Analytic Professional, Certified in Islamic Capital Markets and Instruments, Certified Wealth Manager, and Qualified Wealth Planner. With her academic experience, publications, and professional certifications, she actively contributes to the development of financial research and education that is relevant to industry and society.', null, 'repo:migrated/people/atika-irawan-smn-msc-phd-cand.webp', 'https://www.linkedin.com/in/atika-irawan/', 4, true),
  ('achmad-billy-zulqiyami-st-sh-mh-phd-cand', 'Achmad Billy Zulqiyami, S.T., S.H., M.H., Ph.D. (Cand.)', 'researcher', 'Business Law, Regulation and Policy Studies', 'Hukum Bisnis, Regulasi, dan Kajian Kebijakan', 'Achmad Billy Zulqiyami, S.T., S.H., M.H., Ph.D. (c) is an academic and legal practitioner focusing on business law, contract systems, public regulation, legal due diligence, and policy studies. He is active as a lecturer in Business Law and Contract System at Institut Teknologi Bandung and is currently pursuing his doctoral studies in law at Universitas Padjadjaran.

He has extensive experience in drafting regulations, academic papers, legal opinions, feasibility studies, and legal advisory work for various government institutions, state-owned enterprises, and corporations. His engagements include projects with the Ministry of Energy and Mineral Resources, Ministry of Public Works and Housing, Ministry of Agrarian Affairs and Spatial Planning, local governments, ANTAM, Pertamina, Biofarma, Bukit Asam, and various regional-owned enterprises.

With a multidisciplinary background in civil engineering and law, he has the capacity to bridge regulatory, business, infrastructure, and public policy aspects. His experience in legal drafting, due diligence, regulatory development, and corporate studies strengthens his role in supporting legal governance and analysis-based strategic decision-making.', null, 'repo:migrated/people/achmad-billy-zulqiyami-st-sh-mh-phd-cand.webp', 'https://www.linkedin.com/in/achmad-billy-zulqiyami-768643125/', 5, true),
  ('alif-hijriah-ssi-msi', 'Alif Hijriah, S.Si., M.Si.', 'researcher', 'Quantitative Economic Analysis and Modelling', 'Analisis dan Pemodelan Ekonomi Kuantitatif', 'Alif Hijriah, S.Si., M.Si. is an expert, educator, and quantitative economic analysis practitioner focusing on mathematical modelling, economic impact analysis, public policy, and educational communication. He currently serves as an Expert in Economic Impact Analysis for Priority Policies at the Coordinating Ministry for Food Affairs of the Republic of Indonesia, an Expert in Economic and Mathematical Analysis at the Ministry of Higher Education, Science, and Technology, and an Expert in Mathematical Analysis at the Regional Development Planning Agency of West Java Province.

He has experience in various strategic consulting projects, including the analysis of the impact of KDKMP on GDP, poverty rates, and the Gini Ratio, which was presented at a Limited Cabinet Meeting at the Presidential Palace of the Republic of Indonesia. His work also includes studies on energy self-sufficiency, the transition from LPG to electric stoves, the impact of road development on GRDP, Vehicle Operating Cost, Value of Time, CO₂ emissions, and the impact of gas imports on the national economy.

In addition to his role as an expert, he is also the President Commissioner of PT Cerebrum Edukanesia Nusantara and is widely known as Alif Towew, an educational content creator in mathematics, physics, and economics. He earned his Master’s degree in Mathematics through the fast-track program at Institut Teknologi Bandung and his Bachelor’s degree in Mathematics from ITB with Cum Laude distinction. With his combination of mathematical expertise, economic analysis, policy consulting experience, and public communication skills, he actively contributes to supporting data-driven policymaking and broad-impact education.', null, 'repo:migrated/people/alif-hijriah-ssi-msi.webp', 'https://www.instagram.com/aliftowew/', 6, true),
  ('nitha-pricillia-se-mm-phd-cand', 'Nitha Pricillia, S.E., M.M., Ph.D (Cand.)', 'researcher', 'Program Director, CRMS Indonesia', 'Program Director, CRMS Indonesia', 'Nitha Pricillia is the Program Director of the Center for Risk Management and Sustainability (CRMS) Indonesia and a professional in risk management, governance, compliance, and sustainability. She previously served as Chief Operations Officer at Enterprise Risk Management Academy (ERMA) PTE LTD, Singapore, and is also active as an academic at Parahyangan Catholic University. Through her roles, she contributes to strengthening risk management practices, capacity building, professional certification, and the implementation of risk governance standards within organizations.

As both a practitioner and academic, she has experience in training, competency assessment, and research in governance, risk management, and compliance. She is a Certified Professional Trainer in Risk Management, a Certified Assessor for Risk Management Professional Certification, and holds the Enterprise Risk Management Certified Professional (ERMCP) and Qualified Risk Management Professional (QRMP) certifications. One of her notable achievements is receiving the Best Presentation Award at the International Call for Paper and Conference on Governance, Risk Management and Compliance (ICGRC) 2021.

She earned her Master in Management with a concentration in Risk Management from Parahyangan Catholic University with Cum Laude distinction, and a Bachelor in Economics from Padjadjaran University, also with Cum Laude distinction. She is currently pursuing her doctoral studies at Institut Teknologi Bandung. With her combination of professional experience, certifications, academic achievements, research contributions, and continuous academic development, she actively contributes to strengthening risk governance and organizational sustainability in Indonesia.', null, 'repo:migrated/people/nitha-pricillia-se-mm-phd-cand.webp', 'https://www.linkedin.com/in/nitha-pricillia-835936106/', 7, true),
  ('khairil-insan-bintang-spd-mpd', 'Khairil Insan Bintang, S.Pd., M.Pd', 'researcher', 'Researcher, IEEF', 'Peneliti, IEEF', 'Khairil Insan Bintang, S.Pd., M.Pd. is a Researcher at the Institute for Energy, Economics and Finance (IEEF), with a focus on economic analysis, data analysis, financial assessment, and quantitative research. He has experience supporting research projects, data management, report preparation, and investment and financial analysis to support strategic decision-making.

He has been involved in various Input-Output Analysis studies for electricity interconnection projects, including Sumatera–Bintan–Batam, Sumatera–Bangka, Sumatera–Java, and Java–Bali. His contributions include sectoral multiplier calculations, economic impact analysis, data management, as well as supporting academic publications and policy recommendations.

He earned his Bachelor of Economic Education and Master of Economic Education from Universitas Pendidikan Indonesia through a fast-track program. He also has expertise in financial modelling, data processing, ESG, risk management, and analytical tools such as Monte Carlo Simulation, SLS Lattice, SPSS, SmartPLS, EViews, STATA, and Crystal Ball. With his combination of research capability, project administration, data analysis, and financial assessment skills, he actively contributes to data-driven economic and policy studies. In addition, he holds several finance-related certifications, including Financial Modeling & Valuation Analyst (FMVA) Certified and Financial Planning and Professional Analyst (FPAP) Certified.', null, 'repo:migrated/people/khairil-insan-bintang-spd-mpd.webp', 'https://www.linkedin.com/in/khaibintang/', 8, true),
  ('sophia-roosma-hardeny-st-mba', 'Sophia Roosma Hardeny, S.T., MBA.', 'researcher', 'Construction Management and Project Risk', 'Manajemen Konstruksi dan Risiko Proyek', 'Sophia Roosma Hardeny, S.T., MBA. is a senior professional in construction management, project control, civil-architectural engineering, and project risk management. She has more than 20 years of experience in plant and non-plant building construction projects, particularly in the power plant and oil and gas sectors.

She currently serves at Sumitomo Corporation on the Central Java 2x1000 MW Coal Fired Power Plant project, with experience as Site Manager for the Warranty Period, Civil, Architecture & Offshore Division Manager, and Chief Engineer. Previously, she was also involved in various strategic projects with PT Bhimasena Power Indonesia, PT Rekayasa Industri, PT Tripatra Constructors & Engineers, and PT Paiton Energy.

With an architectural engineering background from Institut Teknologi Sepuluh Nopember (ITS) and extensive experience in energy infrastructure projects, she has strong capabilities in construction management, multidisciplinary coordination, project control, and the implementation of HSE standards. She actively contributes to ensuring that project execution aligns with established technical, quality, safety, and design standards.', null, 'repo:migrated/people/sophia-roosma-hardeny-st-mba.webp', 'https://www.linkedin.com/in/sophia-roosma-hardeny-4b351033/', 9, true),
  ('anisya-nurfitri-k-spd-msm', 'Anisya Nurfitri K., S.Pd., M.S.M', 'researcher', 'Project Manager and Research Assistant, IEEF', 'Manajer Proyek dan Asisten Peneliti, IEEF', 'Anisya Nurfitri K., S.Pd., M.S.M. is a Project Manager and Research Assistant at the Institute for Energy, Economics, and Finance (IEEF), with a focus on project management, management research, economic analysis, community development, and consumer behavior. She has experience managing research and consulting projects from planning, data collection, and analysis to report preparation and academic publication.

She has been involved in various strategic projects with LAPI–PGN, the Asian Development Bank, PLN, and SBM ITB, including studies on carbon markets and Renewable Energy Certificates, household gas network feasibility studies, strategic corporate project reviews, the development of PLN Research and Development Center’s long-term corporate plan, and research on electric vehicle consumer behavior. She also supports several research grants related to ASEAN electricity interconnection, the transition from LPG to gas networks, RECs, electric vehicle adoption, and ESG.

She earned her Master of Science in Management from Universitas Padjadjaran with a GPA of 4.00/4.00 and was named Best Graduate of the Master of Science in Management Program at FEB Unpad. Previously, she completed her Bachelor’s degree in Office Management Education at Universitas Pendidikan Indonesia and received the PPA Scholarship. With her experience in research, project management, data analysis, and academic publication, she actively contributes to data-driven studies and impactful policy development.', null, 'repo:migrated/people/anisya-nurfitri-k-spd-msm.webp', 'https://www.linkedin.com/in/anisya-nurfitri-kustyani-m-s-m-9375241b7/', 10, true),
  ('fadhil-nurilman-muhammad-sm-mba', 'Fadhil Nurilman Muhammad, S.M., MBA.', 'researcher', 'Economic Impact and Feasibility Studies', 'Kajian Dampak Ekonomi dan Studi Kelayakan', 'Fadhil Nurilman Muhammad, S.M., MBA. is an entrepreneur and business and economic study consultant with a focus on economic impact evaluation, feasibility studies, cost-benefit analysis, and input-output modelling. He has experience as a project-based Socio-economic Researcher at ITB and STEI ITB, as well as a Regional Economic and Business Consultant at PT Ripta Jagabhumi Nusantara.

He has been involved in various strategic studies, including socio-economic impact analysis for interregional electricity interconnection projects, Leontief-based Input-Output modelling, feasibility studies, commercial and financial due diligence, and regional economic studies for strategic projects such as Indonesia’s New Capital City and regional asset development. In addition, he has entrepreneurial experience as the Founder and Owner of Okosan Gyoza and Bakmie Karet Ayam Kampung H. Man.

He earned his MBA from the School of Business and Management, Institut Teknologi Bandung (SBM ITB), with a concentration in Finance, and his Bachelor’s degree in Management from Universitas Widyatama. One of his notable achievements is winning 1st Place in the MBA ITB Business and Marketing Plan Competition 2023. With his combination of expertise in economic analysis, finance, feasibility studies, and business development, he actively contributes to supporting data-driven strategic decision-making and investment feasibility assessment.', null, 'repo:migrated/people/fadhil-nurilman-muhammad-sm-mba.webp', 'https://www.linkedin.com/in/fadhilnrlmn/', 11, true),
  ('ihda-farhatun-nisak-spd-mm', 'Ihda Farhatun Nisak, S.Pd., M.M.', 'researcher', 'Researcher, IEEF', 'Peneliti, IEEF', 'Ihda Farhatun Nisak, S.Pd., M.M. is a Researcher at the Institute for Energy, Economics and Finance (IEEF) and a lecturer at Institut Ekonomi dan Digital LPKIA. She has expertise in management, marketing, digital customer experience, quantitative research, and data analysis. As a lecturer, she teaches research methodology and statistics.

She has research experience in artificial intelligence in digital services, customer engagement, online repurchase intention, digital marketing, and collaborative governance in poverty alleviation. She is also active in academic publications and presentations at national and international forums, including topics related to digital customer experience, gamification, and digital investment behavior.

She earned her Master’s degree in Management from Universitas Pendidikan Indonesia with early completion, as well as a Bachelor’s degree in Business Education with Best Graduate distinction. With her combination of academic experience, research, publications, data analysis, and digital communication skills, she actively contributes to data-driven studies, policy development, and digital economic transformation.', null, 'repo:migrated/people/ihda-farhatun-nisak-spd-mm.webp', 'https://www.linkedin.com/in/ihdafarhatunnisak/', 12, true);

