insert into public.news (slug, date, place, title_en, title_id, tagline_en, tagline_id, summary_en, summary_id, body_en, body_id, image, source_label, source_url, published) values
  ('press-release-16', '2026-09-30', 'Bandung', '2027 State Budget Sets Rp4,106.26 Trillion in Spending and 6% Growth Target, Leaving Little Room for Error', null, null, null, 'Indonesia’s 2027 State Budget sets spending at Rp4,106.26 trillion with a 6% growth target and a deficit of 2.4% of GDP. Discussed on the Kompas Bisnis program, the analysis highlights the limited room for error, the need to broaden the tax base, quality formal job creation, and well-targeted subsidies as key measures of budget success', null, 'As conveyed by Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., Lecturer at the School of Business and Management, Institut Teknologi Bandung (SBM ITB) and Executive Director of the Institute for Energy, Economics and Finance (IEEF), in a discussion on the Kompas Bisnis program on Wednesday, September 30, 2026, the 2027 State Budget (APBN) passed by the House of Representatives (DPR) should be judged not only by its size, but by the quality of its spending. The budget sets state spending at Rp4,106.26 trillion against state revenue of Rp3,435.10 trillion, producing a deficit of Rp671.16 trillion, or 2.4% of gross domestic product (GDP), built on assumptions of 6% economic growth, 2.5% inflation, an exchange rate of Rp17,500 per US dollar, and an Indonesian Crude Price (ICP) of US$75 per barrel.

The Executive Director of IEEF assessed these targets as aggressive amid global uncertainty, noting that a weaker rupiah coinciding with higher energy prices would exert a double pressure on imports, subsidies, energy compensation, inflation, and fiscal space. A deficit below the 3% ceiling, in his view, does not automatically signal low risk, as fiscal credibility also rests on realistic assumptions, resilience to external shocks, financing costs, with the 10-year Government Securities (SBN) yield assumed at 6.9%, and the productive use of the deficit. “The target is quite aggressive and, in my view, even ambitious, because it leaves very little room for error,” he explained.

On the revenue side, the tax revenue target of Rp2,911.95 trillion may be attainable, but the IEEF Executive Director urged broadening the tax base rather than raising the tax burden on the middle class, formal workers, micro, small and medium enterprises (MSMEs), and already-compliant taxpayers, supported by data integration, stronger compliance, and risk-based supervision. Flexible fiscal space is also smaller than the headline figure, as much of the budget is already committed to education, interest payments, personnel spending, regional transfers of Rp735 trillion, subsidies, and social protection, calling for priority on programs with high marginal return. He further cautioned that workers losing formal jobs may shift into informal work and still be counted as employed, so success should be measured through formal job creation, real wages, labour productivity, the employment elasticity of growth, and social protection coverage. “We should not be trapped by the open unemployment rate. That figure can look good while the quality of jobs is actually declining,” he said.

Overall, the Executive Director of IEEF assessed that the success of the 2027 APBN will depend on spending productivity and targeting accuracy. Mistargeted subsidies, such as the 3 kg LPG subsidy, whether through inclusion error, where ineligible parties receive assistance, or exclusion error, where eligible households are left out, require better databases, beneficiary validation, transparency, and accurate distribution. Over the longer term, fiscal resilience calls for room to reprioritize spending when shocks occur, reduced dependence on oil imports, an accelerated energy transition, and wider use of local currency settlement to lessen reliance on the US dollar. “Fiscal leakage does not only mean money that is lost or misappropriated. Subsidies and social protection that miss their targets are also fiscal leakage,” he concluded.

Source: Kompas Bisnis, September 30, 2026

https://www.youtube.com/watch?v=mmZ8zhGXH4I', null, 'repo:migrated/news/press-release-16.webp', null, null, true),
  ('press-release-15', '2026-08-22', 'Bandung', 'Indonesia’s Economy Grows 5.29% in Second Quarter 2026, Anchored by Domestic Demand', null, null, null, 'Indonesia’s economy grew 5.29% year-on-year in the second quarter of 2026. Published by Media Indonesia, the exposition highlights the central role of household consumption, bank lending, government spending, and continued investment activity in maintaining growth amid global economic uncertainty', null, 'As conveyed by Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., Lecturer at the School of Business and Management, Institut Teknologi Bandung (SBM ITB) and Executive Director of the Institute for Energy, Economics and Finance (IEEF), in an exposition published by Media Indonesia on Saturday, August 22, 2026, the Indonesian economy demonstrated resilience amid global pressure and financial market volatility. The economy grew 5.29% year-on-year (YoY) in the second quarter of 2026, staying above 5% despite moderating from 5.61% in the first quarter, even as geopolitical conflict, trade wars, and currency volatility persisted.

In his State Address on August 14, 2026, President Prabowo Subianto cited investment realization of Rp1,010 trillion in the first semester of 2026 and more than 1.4 million jobs created. Domestic demand, according to Hakam, remains a principal cushion: household consumption grew 5.06% YoY, moderating from 5.52% but still contributing heavily given its share of the economy, supported by contained inflation of 3.34% YoY in June 2026, within Bank Indonesia’s target of 2.5% plus-minus 1%.

Bank lending grew 12.67% YoY in June 2026, with investment loans up 24.90% and working capital loans 8.94%, while the Weighted Net Balance of new loan disbursement rose to 93.08% from 38.74% a quarter earlier. Government consumption also preserved momentum, growing about 15.97% YoY on priority programs, the thirteenth salary for civil servants, and social assistance. “As long as the intermediation function of the banking system continues to operate, capital market volatility does not automatically halt production, investment, and consumption,” he explained.

Overall, the SBM ITB economist assessed that growth of 5.29% shows the economy retains buffers against external pressure: resilient domestic demand, expansive credit, supportive fiscal policy, and reserves of about US$145.6 billion at end-June 2026, equal to some 5.5 months of imports. “Growth of 5.29% is evidence that the Indonesian economy has the capacity to absorb pressure in the short term. The challenge is how to preserve that capacity so that it can support sustainable growth,” he concluded.

Source: Media Indonesia, August 22, 2026 —

https://mediaindonesia.com/nusantara/924811/ekonomi-indonesia-tumbuh-529-permintaan-domestik-jadi-penopang', null, 'repo:migrated/news/press-release-15.webp', null, null, true),
  ('press-release-14', '2026-08-20', 'Bandung', 'Financial Market Pressure Has Not Translated into Real Sector Weakness, SBM ITB Economist Says', null, null, null, 'Financial market volatility has not yet translated into a broad weakening of Indonesia’s real economy. Published on ITB’s official portal, the exposition explains that domestic demand, credit, and ongoing investment projects remained resilient, although prolonged market pressure could eventually increase capital costs and weaken private investment', null, 'The performance of the Indonesian economy in the second quarter of 2026 should be read by distinguishing financial market dynamics from real economic activity. This was conveyed by Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., Lecturer at the School of Business and Management, Institut Teknologi Bandung (SBM ITB) and Executive Director of the Institute for Energy, Economics and Finance (IEEF), in an exposition published by the official ITB portal (itb.ac.id) on Thursday, August 20, 2026, in response to national growth of 5.29% year-on-year (YoY) recorded amid pressure on domestic financial markets.

Hakam explained that market sentiment can shift within days, whereas consumption, credit, investment, production, and employment adjust far more slowly. “Pressure in financial markets has not yet been fully translated into a weakening of real economic activity,” he said. “At the initial stage, such pressure mainly affects asset prices, portfolio allocation, foreign portfolio flows, risk premium, and perceptions of Indonesia’s investment attractiveness. The impact on the real sector will be felt only if it persists into higher cost of capital, slower investment, and diminished job creation.”

One manifestation is Indonesia’s investability: in June 2026, MSCI flagged concerns over shareholder transparency and coordinated trading, and opened the possibility of consulting on a reclassification from Emerging Market to Frontier Market absent improvement by November 2026. Capital flows, however, have not tracked equity market pressure — Bank Indonesia recorded a net inflow of foreign portfolio investment of US$8.5 billion in the quarter, mainly into Government Securities and Bank Indonesia Rupiah Securities. “This is more accurately understood as a shift in portfolio preference and allocation rather than a wholesale exit of foreign capital,” he explained.

Gross Fixed Capital Formation grew 6.87%, though Hakam cautioned this does not automatically signal stronger private investor confidence, as growth was driven largely by construction tied to National Priority Work Programs. Externally, May 2026 exports of US$23.20 billion against imports of US$24.81 billion produced a deficit, yet January–May still posted a US$4.03 billion surplus, with rising imports reflecting demand for raw materials, capital goods, and energy. “The external sector has not been the primary source of growth resilience, but its pressure has also not been large enough to offset domestic demand,” he concluded.', null, 'repo:migrated/news/press-release-14.webp', 'itb.ac.id, August 20, 2026', 'https://itb.ac.id/berita/ekonom-itb-soroti-ketahanan-ekonomi-indonesia-pada-kuartal-ii-2026/63725', true),
  ('press-release-13', '2026-08-07', 'Jakarta', 'Lower Unemployment Must Be Accompanied by More Formal and Productive Jobs', null, null, null, 'Ir. Dzikri Firmansyah Hakam, economist, faculty member at SBM ITB, and Executive Director of IEEF, was invited by KompasTV to discuss Indonesia’s latest employment conditions. He welcomed the decline in the open unemployment rate while emphasizing that labor-market progress should also be measured by the economy’s ability to create formal, productive, and sustainable jobs', null, 'Indonesia’s open unemployment rate declined from 4.68 percent in February 2026 to 4.65 percent in May 2026. This positive development was discussed on Kompas Bisnis, with a focus on the quality and sustainability of employment in Indonesia.

According to Statistics Indonesia (BPS), the national labor force reached 155.41 million people in May 2026, consisting of 148.19 million employed individuals and 7.22 million unemployed individuals. Compared with February 2026, the number of employed people increased by approximately 522,000, while the number of unemployed people decreased by around 24,000.

The decline in unemployment indicates that the economy continues to absorb additional workers. However, the relatively modest decrease of 0.03 percentage points also shows that labor-market improvement remains gradual.

A lower unemployment rate does not automatically mean that workers have access to stable employment, adequate income, social protection, and opportunities for productivity growth. Labor-market progress must therefore be assessed through both the number and quality of jobs created.

The growing number of independent workers may reflect stronger entrepreneurial activity and greater workforce flexibility. At the same time, it may also indicate that formal employment opportunities remain limited, encouraging some workers to rely on self-employment as their primary source of income.

Independent workers require better access to financing, training, digital infrastructure, markets, and social protection. These forms of support are essential to improve productivity, income stability, and economic resilience.

Sustainable employment growth also requires stronger real-sector activity and closer alignment between workforce skills and industry needs. Labor-intensive industries, manufacturing, services, and emerging sectors must be encouraged to expand and create jobs that provide greater stability, clear career development, and higher productivity.

Improving vocational education, strengthening reskilling and upskilling programs, supporting business expansion, and maintaining a favorable investment climate are essential to translate economic growth into broader and higher-quality employment opportunities.

The success of employment policy should not be measured solely by a declining unemployment rate. A healthy labor market must create sufficient formal, productive, and sustainable jobs while providing adequate income, economic security, and opportunities for upward mobility.

Watch the full discussion on KompasTV’s YouTube channel:

https://www.youtube.com/watch?v=yVTRvHuQ61s', null, 'repo:migrated/news/press-release-13.webp', null, null, true),
  ('press-release-11', '2026-06-24', 'Jakarta', 'Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D. Highlights the Importance of Economic Growth That Benefits the Public on Kompas Bisnis KompasTV', null, null, null, 'Ir. Dzikri Firmansyah Hakam, economist, full-time faculty member at SBM ITB, and Executive Director of IEEF, was invited by Kompas TV to discuss Indonesia’s economic growth, purchasing power, and middle-class challenges, emphasizing that growth must be felt through household welfare, income, decent jobs, and upward mobility', null, 'KompasTV invited Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., an economist, faculty member at the School of Business and Management, Institut Teknologi Bandung (SBM ITB), also Executive Director of the Institute for Energy, Economics, and Finance (IEEF), as a speaker on Kompas Bisnis to discuss Indonesia’s economic growth, household purchasing power, and middle-class challenges.

In the discussion titled “Presiden Prabowo: Ekonomi Tumbuh Tapi Rakyat Miskin”, Dzikri explained that economic growth should be understood not only through macroeconomic indicators, but also through how it affects people’s daily lives. Growth needs to be reflected in stronger household purchasing power, more stable income, access to decent jobs, and greater opportunities for upward economic mobility.

One of the key issues discussed was the decline in Indonesia’s middle-class population. Based on BPS data presented during the program, the number of middle-class citizens declined from 53.8 million people in 2021 to 46.7 million people in 2025. The middle class is defined as individuals with monthly per capita expenditure ranging from 3.5 to 17 times the national poverty line. With the national poverty line recorded at Rp641,443 per capita per month, the estimated middle-class expenditure range is between Rp2,245,050 and Rp10,904,531 per month.

According to Dzikri, the decline of the middle class is an important reminder that economic growth must be able to protect household purchasing power. When the cost of living rises, income growth remains limited, and consumption space becomes narrower, households that were previously considered middle class may become more economically vulnerable.

He also explained that economic policy should strengthen household resilience. This can be supported through the creation of productive jobs, stronger real-sector activity, better control of essential goods prices, improved quality of public spending, and programs that directly contribute to public welfare.

Through his appearance on KompasTV, Dzikri emphasized that the success of economic policy should not be measured only by growth figures, but also by how far that growth is felt by the public. Quality growth is growth that protects purchasing power, expands job opportunities, strengthens the middle class, and enables people to live more prosperous lives.

Watch the full discussion on KompasTV’s YouTube channel.

https://youtu.be/IT03YUuKJwY?si=fNajMXWn0_hdKxKk', null, 'repo:migrated/news/press-release-11.webp', null, null, true),
  ('press-release-12', '2026-06-24', 'Bandung', 'Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D. Highlights the Importance of Economic Growth That Delivers Real Benefits for Society at Lemhannas RI FGD', null, null, null, 'Ir. Dzikri Firmansyah Hakam, economist, full-time faculty member at SBM ITB, and Executive Director of IEEF, was invited by Lemhannas RI to discuss quality economic growth, justice, and equitable welfare, highlighting the need to turn strong economic figures into real benefits for communities and public prosperity', null, 'Lembaga Ketahanan Nasional Republik Indonesia (Lemhannas RI) invited Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., an economist, faculty member at the School of Business and Management, Institut Teknologi Bandung (SBM ITB), also Executive Director of the Institute for Energy, Economics, and Finance (IEEF), as a speaker in a Focus Group Discussion (FGD) titled “Penguatan Pertumbuhan Ekonomi yang Berkualitas untuk Mewujudkan Keadilan dan Pemerataan Kesejahteraan Rakyat.”

The discussion was held on Wednesday, June 24, 2026, in Bandung, as part of the preparation of policy recommendations for the 2026 Long-Term Strategic Study. The forum provided a space to discuss how Indonesia’s economic growth can be directed not only toward stronger macroeconomic performance, but also toward more meaningful outcomes for society.

In the forum, Dzikri explained that quality economic growth should be assessed by its real impact on people’s daily lives. Growth should not be measured only through output, investment, or other macroeconomic indicators. It should also be reflected in productive jobs, stronger purchasing power, wider economic opportunities, and more equal welfare outcomes.

He also emphasized the important role of universities in supporting regional and national economic development. Universities should not only function as centers of education and research, but also as strategic partners for government and industry in developing evidence-based, relevant, and practical solutions to development challenges.

Through the triple-helix approach, which connects government, industry, and universities, research and innovation can be translated more effectively into policies, programs, products, and business models that generate direct benefits for society. This collaboration is essential to support structural transformation, improve productivity, expand employment opportunities, and strengthen regional competitiveness.

In the context of West Java, universities hold a strategic position because they are closely connected to industrial centers, innovation ecosystems, and regional development needs. With relevant research and stronger cross-sector collaboration, universities can help accelerate the development of higher-value sectors, improve human capital, and open broader economic opportunities for the public.

Dzikri conveyed that economic development should not be judged only by higher growth figures. Truly quality growth is growth that creates economic security, expands decent employment, protects purchasing power, reduces inequality, and enables people to live more prosperous lives.

Through his participation in the Lemhannas RI FGD, Dzikri encouraged the importance of economic policies that are evidence-based, collaborative, and focused on tangible benefits for society. Ultimately, economic growth should not only look strong on paper, but also improve people’s quality of life and broaden public welfare.', null, 'repo:migrated/news/press-release-12.webp', null, null, true),
  ('press-release-9', '2026-06-17', 'Jakarta', 'SBM ITB Economist Featured on Kompas TV to Discuss Indonesia’s Economic Developments', null, null, null, 'Ir. Dzikri Firmansyah Hakam, economist, full-time faculty member at SBM ITB, and Executive Director of IEEF, was invited by Kompas TV to discuss the recent strengthening of the Rupiah, fiscal policy evaluation, energy price adjustment, and their implications for inflation, monetary policy, and household purchasing power', null, 'Kompas TV invited Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., an economist, full-time faculty member at the School of Business and Management, Institut Teknologi Bandung (SBM ITB), and Executive Director of the Institute for Energy, Economics, and Finance (IEEF), to provide expert commentary on Indonesia’s latest economic developments, particularly the strengthening of the Rupiah, fiscal policy evaluation, energy price adjustment, monetary policy direction, and their implications for household purchasing power.

The discussion highlighted the recent appreciation of the Rupiah to the Rp17,700–Rp17,900 range per US dollar, which was positively received by financial markets. According to Ir. Dzikri, this strengthening should not be attributed solely to the government’s evaluation of major programs such as Makan Bergizi Gratis (MBG) and Koperasi Desa (Kopdes). Rather, it reflects a combination of external and domestic factors, including the weakening of the US dollar, improved attractiveness of Rupiah-denominated assets, foreign capital inflows into government securities and Bank Indonesia instruments, as well as policy communication from Bank Indonesia.

He emphasized that the evaluation of MBG and Kopdes served more as a positive signal of fiscal credibility than as the main driver of Rupiah appreciation. For investors, the move indicates that government priority programs are not treated as open-ended spending commitments. Instead, their scale, timing, governance, and effectiveness remain subject to evaluation when fiscal pressures increase. This is important as markets continue to assess whether Indonesia can balance its growth ambitions with sound public finance management.

The discussion also addressed the recent increase in Pertamax prices. Ir. Dzikri explained that the adjustment may help reduce indirect fiscal pressure when global oil prices and exchange rate movements increase fuel procurement costs. However, he underlined that the credibility of market-based fuel pricing depends not only on the government’s willingness to raise prices when costs rise, but also on its consistency in lowering prices when oil prices decline and the Rupiah strengthens. A transparent two-way pricing mechanism is essential to maintain public trust.

On inflation, he noted that a stronger Rupiah can help reduce imported inflation, particularly for energy, food, raw materials, and other goods priced in US dollars. However, the benefits will only be felt by the public if lower import costs are transmitted effectively into domestic prices. Without a responsive pricing mechanism, currency appreciation may remain a positive market indicator without immediately improving household purchasing power.

Regarding MBG and Kopdes, Ir. Dzikri stressed that evaluation does not mean discontinuation. Both programs have important social and economic objectives. MBG aims to improve nutrition while supporting local economic activity, while Kopdes seeks to strengthen village-based economic institutions. However, large-scale programs require strong governance, measurable outcomes, efficient budget execution, and clear accountability.

In relation to Bank Indonesia’s policy direction, Ir. Dzikri argued that BI should not rush to lower interest rates. The recent BI Rate increase to 5.50 percent has helped restore confidence in Rupiah assets. However, once exchange rate and inflation pressures are more firmly under control, gradual monetary easing may be considered to support consumption, investment, MSMEs, housing, and labor-intensive sectors.

Through his appearance on Kompas TV, Ir. Dzikri reaffirmed the importance of evidence-based economic analysis in understanding Indonesia’s macroeconomic direction. He emphasized that the ultimate success of current policy coordination should not only be measured by market confidence, but also by its ability to maintain price stability, protect purchasing power, create jobs, and strengthen Indonesia’s long-term economic resilience.', null, 'repo:migrated/news/press-release-9.webp', null, null, true),
  ('press-release-10', '2026-04-29', 'Jakarta', 'RECLICKS by PYC Awards Research Grant for ASEAN Electricity Market Integration Study', null, null, null, 'RECLICKS by PYC, in collaboration with the FINCAPES Project, University of Waterloo, selected a research project led by Ir. Dzikri Firmansyah Hakam from SBM ITB. The study applies real options valuation to assess Indonesia–Singapore electricity interconnection and its relevance to regional energy policy', null, 'The Purnomo Yusgiantoro Center (PYC), through its RECLICKS by PYC initiative in collaboration with the FINCAPES Project, University of Waterloo, successfully convened a highly competitive and prestigious research grant awarding program aimed at identifying, selecting, and supporting high-impact research initiatives in the fields of climate finance and energy transition. The program brought together a diverse pool of researchers, policymakers, academics, and practitioners, creating a rigorous and merit-based selection environment that emphasized analytical depth, policy relevance, and implementation feasibility.

Designed as a selective platform, the program featured a multi-stage evaluation process, including proposal screening, expert-led assessment, and intensive proposal pitching sessions. Participating teams were required to demonstrate not only strong academic foundations, but also the ability to translate research into actionable policy insights aligned with Indonesia’s energy transition priorities. This competitive process positioned the program as a strategic gateway for advancing policy-oriented research, distinguishing it as a credible and high-standard initiative within Indonesia’s research and policy ecosystem.

The grant awarding process was conducted as part of the CLICKS Workshop titled “Strengthening Research Implementation for Climate Finance and Energy Transition,” held over two days. The workshop functioned as a facilitative and supporting platform, enabling engagement between participants and experts, as well as providing a structured environment for proposal refinement and knowledge exchange. While the primary objective remained the identification and selection of outstanding research proposals, the workshop setting allowed for a more dynamic and interactive evaluation process.

One of the highlighted research projects selected through this competitive platform is titled “Valuing Strategic Flexibility in ASEAN Electricity Market Integration: Real Options Evidence from the Indonesia–Singapore Interconnection.” The study is led by Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., CFP® (Lecturer, SBM ITB) and developed in collaboration with Atika Irawan, M.S., Ph.D (Cand) (Lecturer, SBM ITB) and Nitha Pricillia, S.E., M.M., Ph.D (Cand) (Lecturer, BINUS University). The research is further supported by researchers from the Institute for Energy, Economics and Finance (IEEF), namely Khairil Insan Bintang, M.Pd.; Ihda Farhatun Nisak, M.M.; and Anisya Nurfitri Kustyani, M.S.M, as well as Wahyu Parbowo, S.T., MBA (Cand) (Student, SBM ITB). The project was recognized for its strong analytical framework, particularly in applying real options valuation to assess strategic flexibility in cross-border electricity market integration, as well as its clear relevance to regional energy policy development.

As a complementary component, the program incorporated a set of targeted capacity-building sessions, focusing on enhancing participants’ ability to communicate research findings to policymakers, develop actionable and policy-relevant recommendations, and integrate Gender and Socio-economic Inclusivity (GESEI) into research design. These sessions were intentionally positioned as supporting elements to ensure that awarded research projects are not only academically rigorous but also implementation-ready and capable of generating tangible policy impact.

Through this initiative, RECLICKS by PYC reinforces its role as a strategic enabler of high-quality, policy-driven research, strengthening the linkage between research, funding, and implementation. The program underscores the importance of building a robust research ecosystem where competitive selection, expert validation, and targeted support mechanisms converge to accelerate evidence-based policymaking, optimize climate finance strategies, and advance Indonesia’s sustainable energy transition', null, 'repo:migrated/news/press-release-10.webp', null, null, true),
  ('press-release-8', '2026-03-02', 'Bandung', 'Research and Innovation Recognition at the 67th Dies Natalis of Institut Teknologi Bandung', null, null, null, 'Academic achievements in Scopus-indexed Q1 and Q2 journals were formally recognized during ITB’s 67th Dies Natalis. In 2025, 21 publications contributed to strengthening ITB’s research performance in energy economics and sustainable finance', null, 'Institut Teknologi Bandung (ITB) held the 67th Dies Natalis Open Senate Session on Monday, March 2, 2026, at Aula Barat, ITB Ganesha Campus. The event served as a moment to reflect on the university’s achievements while reinforcing its commitment to impactful research and innovation.

The ceremony was attended by members of the Board of Trustees (MWA), Academic Senate, Forum of Professors, faculty and school leaders, students, and institutional partners. Chair of the ITB Board of Trustees and Minister of Health of the Republic of Indonesia, Budi Gunadi Sadikin, emphasized the importance of collaboration between academia, government, and industry to strengthen Indonesia’s innovation ecosystem and accelerate the downstreaming of research into practical applications.

ITB Rector Prof. Dr. Ir. Tatacipta Dirgantara, M.T. highlighted the university’s strategic direction toward achieving a Top 150 global university ranking by 2030, supported by interdisciplinary collaboration and research aligned with the vision of “ITB Berdampak.”

The event also featured a scientific oration by Prof. Dr. apt. Elfahmi, S.Si., M.Si., Director of Research and Innovation at ITB, titled “Downstreaming and Commercialization of Indonesian Natural Product Research and Innovation for Health Independence.” The oration emphasized the importance of transforming research into tangible products to strengthen Indonesia’s health independence.

During the ceremony, Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., Associate Professor at the School of Business and Management (SBM ITB) and Executive Director of the Institute for Energy, Economics & Finance (IEEF) received the Award for Excellence in Research and Innovation.

In 2025 alone, 21 Scopus-indexed Q1 and Q2 journal publications were produced, contributing to ITB’s research performance, particularly in the fields of energy economics, sustainable finance, and low-carbon development.

The Dies Natalis celebration reaffirmed ITB’s commitment to strengthening impactful research and interdisciplinary collaboration in addressing national development challenges.', null, 'repo:migrated/news/press-release-8.webp', null, null, true),
  ('press-release-7', '2026-02-02', 'Bandung, West Java', 'KOMDIGI, IEEF, and SBM ITB Discuss the Development of Indonesia’s Green Technology Industry', null, 'Green Technology and Electric Vehicles in Indonesia’s Energy Transition and Economic Transformation', null, 'KOMDIGI, IEEF, and SBM ITB convened a policy dialogue on the development of green technology in Indonesia, with a focus on electric vehicles within the national energy transition and low-carbon economy agenda', null, 'The Ministry of Communication and Digital Affairs of the Republic of Indonesia (KOMDIGI), through the Directorate General of Digital Ecosystem, convened a Policy Dialogue on the Development of Green Technology Industry on February 2, 2026, held in Bandung, West Java. The forum was organized as part of an analytical initiative to facilitate the adoption of green technology–based digital solutions in support of Indonesia’s economic and energy transition agenda.

The policy dialogue brought together the Institute for Energy, Economics & Finance (IEEF) and the School of Business and Management, Institut Teknologi Bandung (SBM ITB) as academic and policy research partners. The discussion aimed to develop a comprehensive understanding of Indonesia’s green technology ecosystem, with a particular focus on electric vehicles (EVs), and to gather conceptual and policy-oriented inputs aligned with the 2025–2029 National Medium-Term Development Plan (RPJMN).

During the session, Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., Executive Director of IEEF, served as a resource person, alongside Ir. Lucia Diawati, Ph.D. (ITB). The discussion covered the conceptual framework of green technology, the current landscape of Indonesia’s green technology industry, challenges in ecosystem development, and the role of electric vehicles in advancing decarbonization, energy efficiency, and industrial transformation.

The forum highlighted electric vehicles as a priority use case within Indonesia’s green technology agenda. While available data indicate a high level of user satisfaction with EV adoption, the discussion identified persistent structural challenges, including infrastructure readiness, upfront investment costs, and the need for better alignment between energy policies and market instruments. As such, the development of green technology was discussed not only as a technological issue, but also as a broader industrial, regulatory, and market development agenda.

In line with the forum’s Terms of Reference, the discussion focused on four key areas:
(1) mapping the national green technology ecosystem and industry landscape;
(2) identifying relevant green technology business models suitable for the Indonesian context;
(3) facilitating green technology–based startups and innovation from early-stage development to scale-up; and
(4) determining priority use cases and sectors with high potential impact at both national and subnational levels.

According to Ir. Dzikri Firmansyah Hakam, Ph.D., the development of green technology should be positioned as part of Indonesia’s long-term economic competitiveness strategy. “Green technology should not be viewed solely as an environmental instrument, but also as an enabler of new economic value creation, industrial development, and national energy resilience,” he stated during the discussion.

Through this policy dialogue, KOMDIGI, IEEF, and SBM ITB reaffirmed the importance of collaboration between government, academia, and policy research institutions in shaping a structured and credible green technology ecosystem. The outcomes of the discussion are expected to contribute to future policy recommendations and strategic frameworks for strengthening Indonesia’s green technology industry.', null, 'repo:migrated/news/press-release-7.webp', null, null, true),
  ('press-release-3', '2026-01-09', 'Lombok Tengah', 'IEEF and SBM ITB Enhance Financial Literacy in Mertak Village, Central Lombok', null, 'Connecting Local Potential, Financial Literacy, and Inclusive Economic Growth', null, 'IEEF and SBM ITB implemented a community engagement program in Mertak Village to enhance financial literacy and support inclusive local economic development surrounding the Mandalika tourism area', null, 'The Institute for Economy, Energy, and Finance (IEEF), in collaboration with the School of Business and Management, Institut Teknologi Bandung (SBM ITB), implemented a community development and financial literacy program in Desa Mertak, Kecamatan Pujut, Central Lombok, aimed at strengthening local economic capacity and promoting inclusive development in villages surrounding the Mandalika Special Economic Zone (SEZ). The program was supported by the Lembaga Pengelola Dana Pendidikan (LPDP) and conducted in partnership with academics from Universitas Pendidikan Indonesia (UPI) and Universitas Padjadjaran (Unpad).

The initiative was led by Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., CFP®, a faculty member at SBM ITB and Executive Director of IEEF, together with Khairil Insan Bintang, M.Pd. and Ihda Farhatun Nisak, S.Pd., M.M. (UPI), as well as Anisya Nurfitri K., S.Pd., M.S.M. (Unpad). The collaboration reflects a cross-university effort to integrate academic knowledge, policy insight, and community engagement in addressing local development challenges.

The community engagement program was designed in response to the rapid growth of the Mandalika tourism area, which has generated significant economic opportunities but has yet to deliver inclusive benefits for surrounding villages. Despite its strategic location near international tourism destinations and the Mandalika Circuit, Desa Mertak continues to face challenges in translating its natural and economic potential into tangible welfare improvements. Limited financial literacy, business management capacity, and institutional readiness remain key barriers preventing residents from fully participating in the regional economic transformation.

To better understand local conditions, the IEEF–SBM ITB team conducted field surveys and socio-economic mapping to identify the village’s economic structure and development potential. The assessment revealed that Desa Mertak’s economy is primarily supported by tourism, agriculture, fisheries, and livestock. Community-managed tourism assets such as Pantai Batu Berang, mangrove conservation areas, homestay programs, and boat rental services are operated through Village-Owned Enterprises (BUMDes) and the Tourism Awareness Group (Pokdarwis). While these initiatives demonstrate strong local ownership, they require improved financial governance and managerial capacity to ensure long-term sustainability.

The program also highlighted a structural gap between Desa Mertak’s role as a buffer village for the Mandalika SEZ and the limited economic impact experienced by its residents. This concern was echoed by Moh. Syahnan, Head of Desa Mertak, who noted that insufficient human resource capacity and financial literacy have constrained the community’s ability to capitalize on increasing tourism flows, resulting in local residents remaining largely spectators of regional development.

To address these challenges, the program delivered contextualized financial literacy training covering household financial management, basic bookkeeping for micro and small enterprises, simple business planning, and the introduction of appropriate and low-risk investment instruments tailored to rural contexts. In line with IEEF’s mandate as a policy and economic research institute, the training emphasized inclusive economic development, positioning financial literacy as a foundation for sustainable local growth rather than short-term income generation. The program also focused on developing local financial literacy facilitators to support long-term knowledge retention within the community.

According to Ir. Dzikri Firmansyah Hakam, Ph.D., CFP®, financial literacy is a critical enabler of inclusive development in strategic economic zones. “The economic opportunities created by Mandalika are substantial. However, without financial management capabilities, local communities risk being excluded from these opportunities. Financial literacy empowers communities to actively participate in development and strengthens local economic resilience,” he stated.

Program effectiveness was assessed through pre-test and post-test evaluations, which indicated a measurable improvement in participants’ understanding of structured financial management and long-term planning. These findings suggest that combining community-based engagement with evidence-informed economic perspectives—an approach central to IEEF’s work can generate meaningful capacity improvements at the village level.

Through this initiative, IEEF and SBM ITB, together with UPI and Unpad, reaffirm their commitment to bridging academic research, policy insight, and grassroots empowerment. The Desa Mertak program represents a broader effort to promote inclusive, competitive, and sustainable local economic development, particularly in areas affected by large-scale strategic projects. Supported by LPDP, this collaboration underscores the role of universities and think tanks in ensuring that national development agendas translate into tangible benefits for communities at the grassroots level.', null, 'repo:migrated/news/press-release-3.webp', null, null, true),
  ('press-release-4', '2025-12-12', 'Jakarta', 'From NPV to ENPV: Integrating Multiplier Effects into Energy Project Feasibility Assessment', null, 'Advancing Evidence-Based Energy Investment Decisions through Economic Impact Analysis', null, 'The Sustainable Energy Finance (SEF) Forum – Training Session 3 convened policymakers, SOEs, financial institutions, and development partners to discuss the integration of multiplier effects and Economic Net Present Value (ENPV) into energy project feasibility assessment, strengthening evidence-based energy investment decisions in Indonesia', null, 'Jakarta, December 12, 2025 – The Sustainable Energy Finance (SEF) Forum – Training Session 3, jointly organized by Badan Perencanaan Pembangunan Nasional (Bappenas) and Deutsche Gesellschaft für Internationale Zusammenarbeit (GIZ) through the CASE for Southeast Asia Programme, convened policymakers, state-owned enterprises, financial institutions, development partners, and research organizations to discuss Multiplier Effects and Quantitative Project Feasibility Assessment. The forum was held on 12 December 2025 in Jakarta and forms part of the SEF Forum capacity-building series on sustainable energy finance.

The session highlighted the importance of moving beyond conventional Net Present Value (NPV) analysis toward Economic Net Present Value (ENPV) as a more comprehensive framework for assessing energy investments. ENPV integrates multiplier effect analysis to capture broader economic impacts, including employment generation, local value creation, and inter-sectoral linkages dimensions that are critical for aligning energy projects with national development objectives and public policy priorities.

As part of the technical program, participants were introduced to quantitative methodologies for measuring multiplier effects in renewable energy projects, particularly within the power sector. These approaches enable decision-makers to assess not only the financial viability of projects, but also their contribution to economic growth, fiscal efficiency, and structural transformation. The discussion underscored that energy transition investments are not merely technological or financial undertakings, but strategic development interventions with wide-ranging socioeconomic spillovers.

The forum also addressed Indonesia’s broader energy transition context, including the government’s targets under the RPJMN 2025–2029 and the PLN Electricity Supply Business Plan (RUPTL) 2025–2034, which anticipate substantial private-sector participation and large-scale investment requirements. In this setting, ENPV-based appraisal was emphasized as a critical tool to support evidence-based policymaking, prioritize high-impact projects, and strengthen coordination between fiscal policy, energy planning, and sustainable finance mechanisms.

The multiplier effect module was delivered by Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., Executive Director of Institute for Energy, Economics & Finance (IEEF) and faculty member at SBM ITB. The session demonstrated how ENPV-based feasibility assessment can complement traditional financial indicators such as IRR, DSCR, and LCOE by embedding economic impact considerations into project evaluation and investment decision-making processes.

Through its participation and technical contribution, IEEF reaffirmed its commitment to promoting evidence-based approaches that integrate energy, economic, and financial perspectives. By advancing the application of ENPV and multiplier effect analysis, IEEF supports the development of more robust, transparent, and development-oriented frameworks for sustainable energy policy and investment in Indonesia', null, 'repo:migrated/news/press-release-4.webp', null, null, true),
  ('press-release-6', '2025-12-12', 'Jakarta', 'IEEF Participates in Research Partnership Workshop #1 at CSIS Indonesia', null, 'Advancing Decarbonization Research for Sustainable Development', null, 'The Institute for Energy, Economics & Finance (IEEF) participated in the Research Partnership Workshop #1 organized by the Decarbonization for Development Lab (DfD Lab) at CSIS Indonesia, contributing to discussions on climate policy, economic dynamics, and sustainable investment to support Indonesia’s low-carbon development pathway', null, 'Jakarta, December 12, 2025 – The Institute for Energy, Economics & Finance (IEEF) participated in Research Partnership Workshop #1, organized by the Decarbonization for Development Lab (DfD Lab) at Centre for Strategic and International Studies (CSIS) Indonesia. The workshop forms part of a broader initiative to strengthen policy-oriented research on decarbonization pathways and their interaction with economic development in Indonesia.

The workshop convened researchers, policy experts, and institutional partners to exchange perspectives on advancing evidence-based climate and development research. It served as a strategic platform to foster collaboration across institutions and to ensure that emerging research agendas remain responsive to Indonesia’s development priorities amid global climate and energy transition challenges.

During the Research Partner Presentation session, Nitha Pricillia, Research Fellow at IEEF, presented a research proposal examining the linkages between climate policy, economic dynamics, and their implications for sustainable development and investment in Indonesia. The proposed study aims to provide analytical insights into how climate policy instruments can be designed to support both decarbonization objectives and long-term economic resilience.

The presentation was followed by an in-depth discussion with designated discussants and workshop participants, who provided constructive feedback on the research scope, methodological approach, and policy relevance. The exchange highlighted the importance of interdisciplinary and cross-institutional dialogue in refining research frameworks and ensuring that analytical outputs can effectively inform future policy decisions.

Through its participation in the workshop, IEEF reaffirmed its commitment to contributing rigorous, policy-relevant research that bridges climate action and economic development. Engagement in the DfD Lab research partnership underscores IEEF’s role in supporting collaborative knowledge generation to guide Indonesia’s transition toward a low-carbon and sustainable development pathway.', null, 'repo:migrated/news/press-release-6.webp', null, null, true),
  ('press-release-5', '2025-12-10', 'Bandung', 'IEEF–SBM ITB and PT Geo Dipa Energi (Persero) Strengthen Governance and Executive Leadership in the Geothermal Sector', null, 'Strengthening Governance, Risk Management, and Executive Decision-Making for Indonesia’s Energy Transition', null, 'IEEF, SBM ITB, and PT Geo Dipa Energi (Persero) strengthened governance and executive leadership to support Indonesia’s geothermal energy transition', null, 'Bandung, December 10, 2025 – The School of Business and Management, Institut Teknologi Bandung (SBM ITB), in collaboration with PT Geo Dipa Energi (Persero), organized a series of Professional Knowledge Sharing Sessions aimed at strengthening the strategic role of the Board of Directors and Board of Commissioners in addressing governance and risk dynamics within the geothermal sector. The sessions served as a strategic forum to deepen executive-level perspectives on corporate governance, risk management, and leadership in the context of Indonesia’s energy transition.

The first session, “Governance, Risk & Executive Leadership,” held on December 10, 2025, explored Governance, Risk, and Compliance (GRC) practices at the executive level, strategic risk perspectives, and supply chain vulnerabilities in geothermal project development. The discussion also reflected on the evolving leadership challenges faced by renewable energy enterprises, highlighting the importance of adaptive and inclusive executive leadership in ensuring organizational resilience and project sustainability.

This series was preceded by a session entitled “Strategic Leadership for Energy Transformation,” conducted on November 28, 2025. Through dialogue with senior professionals and academics, the session emphasized the importance of board-level agility, the strengthening of governance-driven leadership culture, and insights drawn from global energy leadership benchmarks as strategic references for corporate leaders navigating uncertainty and accelerating the energy transition.

Both sessions were moderated by the Executive Director of Institute for Energy, Economics & Finance (IEEF), Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D.. He underscored that strong governance and board-level leadership are fundamental to effective strategic decision-making in the energy sector. Amid global volatility and mounting transition pressures, he noted, the quality of governance and executive leadership acumen plays a decisive role in determining project success and long-term corporate resilience.

Through this collaboration, SBM ITB, PT Geo Dipa Energi (Persero), and IEEF reaffirm their shared commitment to building strategic leadership capacity, strengthening governance and risk management practices, and promoting executive decision-making aligned with sustainability principles. This initiative is expected to contribute to the advancement of Indonesia’s geothermal sector as a key pillar of the national energy transition agenda.', null, 'repo:migrated/news/press-release-5.webp', null, null, true),
  ('press-release-2', '2025-09-02', 'Bandung', 'Asahi Glass Foundation Grant Ceremony & Seminar on Research Findings 2025', null, null, null, 'Institut Teknologi Bandung (ITB), supported by The Asahi Glass Foundation, hosted the AF Grant Ceremony & Seminar on Research Findings 2025. The event gathered researchers, academics, and stakeholders to discuss energy, environment, and sustainable development, featuring IEEF Executive Director Ir. Dzikri Firmansyah Hakam, Ph.D., CFP as keynote speaker', null, 'Bandung, September 2, 2025 – Institut Teknologi Bandung (ITB), with the support of The Asahi Glass Foundation, organized the AF Grant Ceremony & Seminar on Research Findings 2025 at the East Campus Center Auditorium, Jl. Ganesha No.10, Bandung.

This annual event aims to strengthen international research collaboration while fostering innovations in the fields of energy, environment, and sustainable development. In this year’s program, AF Grant recipients presented their strategic research findings that contribute to the advancement of science and technology, with a focus on environmental sustainability, renewable energy, and socio-economic impact.

One of the main highlights of the event was the presence of Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., CFP, Executive Director of IEEF (Institute for Energy, Economics, and Finance), as the keynote speaker. He delivered a presentation titled “Environmental, Social, and Governance (ESG) Impact on Corporate Financial Strategies of Global Energy Company.”

In his remarks, Dr. Hakam emphasized how the implementation of ESG principles increasingly influences the direction of financial strategies for global energy companies. ESG is no longer merely a compliance standard but has become a determining factor for competitiveness and business sustainability amid the global energy transition. The event opened with welcoming speeches from ITB leadership and representatives of The Asahi Glass Foundation, reaffirming their joint commitment to supporting high-quality research. In addition to the grant awarding ceremony, the seminar also featured interactive academic discussions that brought together young researchers, senior academics, and cross-sector stakeholders.

“The AF Grant Ceremony & Seminar on Research Findings 2025 is not only a form of appreciation for the grant recipients but also a strategic space to strengthen international research networks and generate new ideas in addressing global challenges,” said one of the organizing committee members. Through this event, it is expected that sustainable collaboration between Indonesia and Japan will be fostered, along with tangible research contributions to sustainable development and energy transition at the global level.', null, 'repo:migrated/news/press-release-2.webp', null, null, true),
  ('press-release-1', '2025-08-23', 'Jakarta', 'IEEF Hadiri PYC International Energy Conference 2025', null, 'Towards Indonesia Emas 2045: Aligning Energy Security, Economic Growth, and Environmental Sustainability', null, 'The Indonesia Energy Economics Forum (IEEF) participated in the PYC International Energy Conference 2025, which carried the theme “Towards Indonesia Emas 2045: Aligning Energy Security, Economic Growth, and Environmental Sustainability.” IEEF’s participation in this forum underscores its commitment to fostering academic discussions, research, and cross-sector', null, 'Jakarta, August 23, 2025 – Institute for Economy, Energy, and Finance (IEEF) participated in the PYC International Energy Conference 2025, which carried the overarching theme “Towards Indonesia Emas 2045: Aligning Energy Security, Economic Growth, and Environmental Sustainability.” This event served as a pivotal forum to discuss Indonesia’s strategies for safeguarding energy security, driving economic growth, and ensuring environmental sustainability in pursuit of the Indonesia Emas 2045 vision.

The conference was attended by high-ranking officials, including H.E. Bahlil Lahadalia, Minister of Energy and Mineral Resources, and H.E. Agus Harimurti Yudhoyono, Coordinating Minister for Infrastructure and Regional Development, whose presence underscored the government’s commitment to aligning energy policies with the trajectory of sustainable national development. Several distinguished speakers also shared strategic insights, among them Anindya Bakrie who presented on “Sustainable Energy as a Catalyst for Green Growth,” Ming Ongkwan, Global Strategy Director of Halliburton, who discussed “Strategic Green Growth: Leveraging Oil & Gas Expertise,” Togu Pardede, Director of Energy Resources, Mineral, and Mining, who emphasized “Indonesia’s Net Zero Target: Embedding Climate Goals in Development Planning,” Achmed Shahram Edianto, PhD, Southeast Asia Transition Partnership (ETP) Indonesia Programme Lead at the United Nations Office for Project Services (UNOPS), who highlighted international institutional support for Indonesia’s energy transition, and Yinglun Teng, Energy Analyst at the IEA Regional Corporate Center, who shared perspectives on “Sustainable Energy for Green Growth.”

IEEF’s Executive Director, Dzikri Firmansyah Hakam, PhD, was also appointed as a jury member for the Call for Papers segment, part of the conference series. His role reflects IEEF’s contribution to strengthening academic research and providing a platform for young scholars and researchers to present innovative ideas related to energy transition and sustainable development. “IEEF’s participation in this international forum highlights our strategic role as a bridge between academia, policymakers, and energy industry stakeholders. IEEF is committed to supporting the achievement of Net Zero Emissions while ensuring an energy transition that aligns with the Indonesia Emas 2045 agenda,” stated an IEEF representative. Through its involvement in the PYC International Energy Conference 2025, IEEF reaffirms its commitment to advancing academic discourse, research, and cross-sector collaboration in building a resilient, equitable, and sustainable energy system for Indonesia’s future.', null, 'repo:migrated/news/press-release-1.webp', null, null, true);

insert into public.careers (slug, title_en, title_id, intro_en, intro_id, qualifications_en, qualifications_id, responsibilities_en, responsibilities_id, notes_en, notes_id, apply_url, poster, is_open, sort, published) values
  ('post-doctoral', null, 'Post Doctoral', null, 'Post Doctoral merupakan posisi peneliti tingkat lanjut yang berperan dalam memimpin, mengembangkan, dan memperkuat agenda riset IEEF di bidang ekonomi energi, keuangan, dan kebijakan publik.', '{}'::text[], array['Domisili Bandung.', 'Lulusan S3 dari bidang Ekonomi, Keuangan, Manajemen, Energi, Kebijakan Publik, atau bidang terkait.', 'Pengalaman sebelumnya dalam proyek dan penelitian merupakan nilai tambah.', 'Memiliki kemampuan dalam analisis ekonomi dan finansial proyek energi melalui salah satu pendekatan berikut: Input-Output Analysis, Real Option Valuation, Project Valuation, Techno-Economic Modelling, Monte Carlo Simulation, LCOE Analysis, Optimization Modelling, atau Data Analytic.', 'Familiar dengan Canva, Microsoft Office, media sosial, serta tools pendukung analisis di bidang ekonomi, energi, dan keuangan seperti Excel, Stata, SPSS, EViews, R, Python, Power BI, Tableau, Bloomberg, Trading Economics, World Bank Data, IEA Statistics, atau platform data lainnya.', 'Memiliki kemampuan komunikasi tertulis dan verbal yang baik dalam Bahasa Indonesia dan Bahasa Inggris.', 'Teliti, proaktif, memiliki kepemimpinan akademik yang baik, dan mampu bekerja dalam tim riset multidisiplin.']::text[], '{}'::text[], array['Memimpin dan melaksanakan penelitian serta proyek di bidang ekonomi energi, keuangan, dan kebijakan publik, mulai dari tahap konsepsi hingga pelaporan hasil.', 'Mengembangkan model analisis ekonomi dan kebijakan energi yang mendukung rekomendasi strategis IEEF kepada mitra nasional dan internasional.', 'Berkontribusi dalam penyusunan policy brief, laporan riset, working paper, dan publikasi ilmiah seperti journal article, conference paper, dan working paper.', 'Melakukan supervisi atau mentoring bagi asisten peneliti, mahasiswa magang, dan tim peneliti junior dalam kegiatan riset.', 'Mewakili IEEF dalam forum akademik dan kebijakan energi, termasuk diskusi, seminar, FGD, workshop, konferensi, dan kolaborasi eksternal.', 'Mendukung pengembangan proposal riset, concept note, kerangka metodologi, serta peluang kolaborasi dengan mitra strategis.']::text[], '{}'::text[], '{}'::text[], 'https://s.id/ieefapply', 'repo:migrated/careers/post-doctoral.webp', true, 1, true),
  ('research-associate', null, 'Research Associate', null, 'SBM ITB bersama Institute for Energy, Economics & Finance (IEEF) membuka kesempatan bagi akademisi dan peneliti untuk berkontribusi dalam pengembangan riset strategis di bidang Energy Economics and Finance.

Posisi ini berada di bawah supervisi langsung Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., CFP®️, dan ditujukan bagi kandidat dengan latar belakang akademik kuat serta rekam jejak publikasi bereputasi internasional.', '{}'::text[], array['Lulusan S3 di bidang relevan.', 'Memiliki minimal 1 publikasi Q1 sebagai penulis pertama (5 tahun terakhir).', 'Memiliki keahlian di Energy Economics and Finance.', 'Mampu bekerja mandiri dan berbasis target.']::text[], '{}'::text[], array['Melaksanakan riset di bidang ekonomi energi dan keuangan.', 'Berkontribusi dalam publikasi ilmiah dan policy brief.', 'Terlibat dalam diskusi riset dan kolaborasi strategis.', 'Mencapai target output riset yang terukur.']::text[], '{}'::text[], array['Periode: April – November 2026', 'Lowongan dibuka hingga posisi terpenuhi.', 'Bergabunglah dan berkontribusi dalam mendorong riset yang berdampak bagi transisi energi Indonesia.']::text[], 'https://s.id/ResearchAssociateSBMIEEF2026', 'repo:migrated/careers/research-associate.webp', true, 2, true),
  ('research-assistant', null, 'Research Assistant', null, 'Research Assistant merupakan posisi yang berperan dalam mendukung kegiatan riset, analisis, dan penyusunan kajian di bidang ekonomi, energi, keuangan, dan kebijakan publik. Posisi ini cocok bagi kandidat yang memiliki minat kuat untuk belajar lebih dalam mengenai isu-isu strategis seperti transisi energi, pembiayaan berkelanjutan, investasi sektor energi, analisis kebijakan, serta pengembangan riset berbasis data. Dalam pelaksanaannya, Research Assistant akan bekerja bersama peneliti senior dan tim multidisiplin untuk membantu proses pengumpulan data, analisis, penulisan laporan, serta penyusunan materi riset dan komunikasi institusi.', '{}'::text[], array['Domisili Bandung.', 'Lulusan S1/S2 atau mahasiswa tingkat akhir dari bidang Ekonomi, Keuangan, Manajemen, Energi, Kebijakan Publik, Teknik Industri, Statistika, atau bidang terkait.', 'Pengalaman sebelumnya dalam proyek dan penelitian merupakan nilai tambah.', 'Melaksanakan analisis di bawah supervisi peneliti senior di salah satu pendekatan berikut: Input-Output Analysis, Real Option Valuation, Project Valuation, Techno-Economic Modelling, Monte Carlo Simulation, LCOE Analysis, dan Optimization Modelling, Data Analytic.', 'Familiar dengan Canva, Microsoft Office, media sosial, serta tools pendukung analisis di bidang ekonomi, energi, dan keuangan seperti Excel, Stata, SPSS, EViews, R, Python, Power BI, Tableau, Bloomberg, Trading Economics, World Bank Data, IEA Statistics, atau platform data lainnya.', 'Memiliki kemampuan komunikasi tertulis dan verbal yang baik dalam Bahasa Indonesia dan Bahasa Inggris.', 'Teliti, proaktif, dan mampu bekerja dalam tim riset multidisiplin.']::text[], '{}'::text[], array['Melakukan kegiatan penelitian dan proyek di bidang ekonomi energi, keuangan, dan kebijakan publik, termasuk pengumpulan data, analisis, dan penyusunan laporan.', 'Melakukan analisis ekonomi dan finansial bidang energi.', 'Berkontribusi dalam penyusunan presentasi, policy brief, dan publikasi ilmiah bersama tim peneliti.', 'Melakukan kegiatan internal IEEF seperti workshop, diskusi riset, serta kegiatan kolaborasi multidisiplin.']::text[], '{}'::text[], '{}'::text[], 'https://s.id/ieefapply', 'repo:migrated/careers/research-assistant.webp', true, 3, true),
  ('internship-program', null, 'Internship', null, 'IEEF membuka kesempatan bagi mahasiswa yang memiliki ketertarikan kuat untuk belajar, berkembang, dan terlibat langsung dalam kegiatan riset di bidang ekonomi, energi, keuangan, dan kebijakan publik. Program internship ini ditujukan bagi kandidat yang ingin memahami isu-isu strategis seperti transisi energi, pembiayaan berkelanjutan, kebijakan ekonomi, analisis data, serta pengembangan riset berbasis evidence-based policy.', '{}'::text[], array['Berdomisili di Bandung.', 'Mahasiswa S1 ongoing minimal semester 4 atau mahasiswa S2 ongoing.', 'Memiliki ketertarikan kuat pada bidang riset, ekonomi, energi, keuangan, dan kebijakan publik.', 'Bersedia belajar dan terlibat dalam proses riset akademik maupun riset kebijakan.', 'Mampu melakukan analisis data, penelusuran literatur, dan penyusunan tulisan ilmiah.', 'Familiar dengan Microsoft Office/Google Workspace, Canva, media sosial, serta tools pendukung analisis di bidang ekonomi, energi, dan keuangan.', 'Memiliki kemampuan komunikasi tertulis dan verbal yang baik dalam Bahasa Indonesia dan Bahasa Inggris.', 'Teliti, proaktif, bertanggung jawab, dan mampu bekerja dalam tim multidisiplin.', 'Memiliki rasa ingin tahu yang tinggi terhadap isu strategis nasional dan global, terutama terkait transisi energi, pembangunan ekonomi, dan pembiayaan berkelanjutan.']::text[], '{}'::text[], array['Mendukung tim riset dalam pengumpulan, pengolahan, dan analisis data kuantitatif maupun kualitatif.', 'Membantu penyusunan literature review, policy brief, laporan riset, dan publikasi akademik.', 'Melakukan desk research terkait isu ekonomi, energi, keuangan, pembangunan berkelanjutan, dan kebijakan publik.', 'Membantu visualisasi data, pembuatan grafik, tabel, dan materi presentasi riset.', 'Terlibat dalam koordinasi kegiatan proyek, termasuk persiapan dokumen, notulensi, dan dukungan administratif teknis.', 'Mendukung penyusunan laporan kegiatan, laporan proyek, serta materi komunikasi riset.', 'Berkontribusi dalam diskusi internal untuk memperkuat kualitas analisis dan rekomendasi kebijakan.']::text[], '{}'::text[], '{}'::text[], 'https://s.id/ieefapply', 'repo:migrated/careers/internship-program.webp', true, 4, true);

